// Prepare context from input
const input = $input.item.json;
const message = input.message;
const classification = input.classification;

// Формируем контекст
const context = classification.context || {
  collectedData: {},
  step: 'initial',
  startedAt: new Date().toISOString()
};

return {
  json: {
    message,
    context,
    classification,
    chatId: message.chat.id,
    userId: message.from.id,
    username: message.from.username
  }
};

// Check LLM Cache
const crypto = require('crypto');
const input = $input.item.json;
const message = input.message;
const context = input.context;

// Генерируем ключ кэша на основе сообщения + контекста
const cacheKey = JSON.stringify({
  text: message.text,
  existingData: context.collectedData
});
const messageHash = crypto.createHash('md5').update(cacheKey).digest('hex');

return {
  json: {
    ...input,
    messageHash,
    checkCache: true
  }
};

// Use cached LLM result
const input = $input.item.json;
const cachedResult = input.cached_result;
const originalData = $('Generate Cache Key').item.json;

return {
  json: {
    ...originalData,
    llmResult: typeof cachedResult === 'string' ? JSON.parse(cachedResult) : cachedResult,
    fromCache: true
  }
};

