// Process DeepSeek response
const input = $input.item.json;
const originalData = $('Generate Cache Key').item.json;

let llmResult;
try {
  const content = input.choices[0].message.content;
  llmResult = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  llmResult = {
    full_name: null,
    phone: null,
    position: null,
    object_location: null,
    is_complete: false,
    missing_fields: ['full_name', 'phone', 'position', 'object_location'],
    clarification_question: 'Не удалось распознать данные. Пожалуйста, укажите ФИО, телефон, должность и объект.'
  };
}

return {
  json: {
    ...originalData,
    llmResult,
    fromCache: false
  }
};

// Merge collected data with new LLM results
const input = $input.item.json;
const context = input.context;
const llmResult = input.llmResult;

// Объединяем ранее собранные данные с новыми
const collectedData = {
  ...context.collectedData,
  ...(llmResult.full_name && { full_name: llmResult.full_name }),
  ...(llmResult.age && { age: llmResult.age }),
  ...(llmResult.gender && { gender: llmResult.gender }),
  ...(llmResult.position && { position: llmResult.position }),
  ...(llmResult.experience && { experience: llmResult.experience }),
  ...(llmResult.phone && { phone: llmResult.phone }),
  ...(llmResult.object_location && { object_location: llmResult.object_location })
};

// Проверяем обязательные поля
const requiredFields = ['full_name', 'phone', 'position', 'object_location'];
const missingFields = requiredFields.filter(f => !collectedData[f]);
const isComplete = missingFields.length === 0;

return {
  json: {
    ...input,
    collectedData,
    isComplete,
    missingFields,
    clarificationQuestion: llmResult.clarification_question
  }
};

// Process duplicate check results
const input = $input.all();
const mainData = $('Merge Data').item.json;
const duplicateResults = input.map(i => i.json);

// Фильтруем дубликаты с высоким совпадением
const highMatchDuplicates = duplicateResults.filter(d => 
  d.similarity_score && d.similarity_score >= 90
);

if (highMatchDuplicates.length > 0) {
  const dup = highMatchDuplicates[0];

  return {
    json: {
      ...mainData,
      hasDuplicate: true,
      duplicate: dup,
      keyboard: {
        inline_keyboard: [
          [
            { text: '➕ Добавить как новый', callback_data: `duplicate_add_${dup.id}` },
            { text: '🔗 Обновить существующий', callback_data: `duplicate_update_${dup.id}` }
          ],
          [
            { text: '❌ Отмена', callback_data: 'duplicate_cancel' }
          ]
        ]
      },
      duplicateMessage: `⚠️ *Найден похожий кандидат* (совпадение ${dup.similarity_score}%):\n\n` +
        `👤 ${dup.full_name}\n` +
        `📞 ${dup.phone}\n` +
        `💼 ${dup.position}\n` +
        `📍 ${dup.object_location}\n` +
        `📊 Статус: ${dup.status}\n` +
        `📅 Добавлен: ${new Date(dup.created_at).toLocaleDateString('ru-RU')}\n\n` +
        `Что сделать?`
    }
  };
}

return {
  json: {
    ...mainData,
    hasDuplicate: false
  }
};

// Build progress message for incomplete data
const input = $input.item.json;
const data = input.collectedData;
const missingFields = input.missingFields;

const requiredFields = ['full_name', 'phone', 'position', 'object_location'];
const optionalFields = ['age', 'gender', 'experience'];

const fieldLabels = {
  full_name: 'ФИО',
  phone: 'Телефон',
  position: 'Должность',
  object_location: 'Объект',
  age: 'Возраст',
  gender: 'Пол',
  experience: 'Опыт'
};

const fieldLabelsRu = {
  full_name: 'ФИО',
  phone: 'Телефон',
  position: 'Должность',
  object_location: 'Объект'
};

// Считаем заполненность
let filledRequired = 0;
let totalRequired = requiredFields.length;

let statusText = '📋 *Данные кандидата*\n\n';

// Обязательные поля
statusText += '*Обязательные:*\n';
for (const field of requiredFields) {
  const value = data[field];
  if (value) {
    statusText += `✅ ${fieldLabels[field]}: ${value}\n`;
    filledRequired++;
  } else {
    statusText += `❌ ${fieldLabels[field]}: _не указано_\n`;
  }
}

// Опциональные поля
statusText += '\n*Дополнительные:*\n';
for (const field of optionalFields) {
  const value = data[field];
  if (value) {
    statusText += `✅ ${fieldLabels[field]}: ${value}\n`;
  } else {
    statusText += `⬜ ${fieldLabels[field]}: _не указано_\n`;
  }
}

// Прогресс-бар
const progress = Math.round((filledRequired / totalRequired) * 100);
const filledBlocks = Math.round(progress / 10);
const progressBar = '█'.repeat(filledBlocks) + '░'.repeat(10 - filledBlocks);
statusText += `\n📊 Заполнено: [${progressBar}] ${progress}%`;

// Кнопки для недостающих полей
const fieldButtons = missingFields.slice(0, 4).map(field => ({
  text: `➕ ${fieldLabelsRu[field] || field}`,
  callback_data: `add_field_${field}`
}));

const keyboard = {
  inline_keyboard: [
    fieldButtons.slice(0, 2),
    fieldButtons.slice(2, 4),
    [{ text: '❌ Отмена', callback_data: 'confirm_cancel' }]
  ].filter(row => row.length > 0)
};

// Уточняющий вопрос
let questionText = input.clarificationQuestion || '';
if (!questionText && missingFields.length > 0) {
  const missingLabels = missingFields.map(f => fieldLabelsRu[f] || f).join(', ');
  questionText = `Пожалуйста, укажите: ${missingLabels}`;
}

return {
  json: {
    ...input,
    statusText,
    keyboard,
    progress,
    questionText
  }
};

// Build confirmation preview for complete data
const input = $input.item.json;
const data = input.collectedData;

const fieldLabels = {
  full_name: 'ФИО',
  phone: 'Телефон',
  position: 'Должность',
  object_location: 'Объект',
  age: 'Возраст',
  gender: 'Пол',
  experience: 'Опыт'
};

let statusText = '📋 *Проверьте данные кандидата*\n\n';

statusText += `👤 *ФИО:* ${data.full_name}\n`;
statusText += `📞 *Телефон:* ${data.phone}\n`;
statusText += `💼 *Должность:* ${data.position}\n`;
statusText += `📍 *Объект:* ${data.object_location}\n`;

if (data.age) statusText += `🎂 *Возраст:* ${data.age}\n`;
if (data.gender) statusText += `👤 *Пол:* ${data.gender}\n`;
if (data.experience) statusText += `📝 *Опыт:* ${data.experience}\n`;

statusText += '\n✅ *Все обязательные поля заполнены!*';
statusText += '\nПроверьте данные и подтвердите сохранение.';

const keyboard = {
  inline_keyboard: [
    [
      { text: '✅ Сохранить', callback_data: 'confirm_yes' },
      { text: '✏️ Изменить', callback_data: 'confirm_edit' }
    ],
    [
      { text: '❌ Отмена', callback_data: 'confirm_cancel' }
    ]
  ]
};

return {
  json: {
    ...input,
    statusText,
    keyboard
  }
};
